171	void SafetyGateNode::RawCmdVelCallback(const geometry_msgs::msg::Twist::SharedPtr msg) {
172	  if (!gate_ || !fault_supervisor_) return;
173	
174	  amr_dispatcher_core::safety::CmdVelCommand cmd;
175	  cmd.linear_x_mps = msg->linear.x;
176	  cmd.linear_y_mps = msg->linear.y;
177	  cmd.angular_z_radps = msg->angular.z;
178	
179	  // 联动 Fault Supervisor 降级限速规则
180	  if (fault_supervisor_->recommendation() == amr_dispatcher_core::safety::SystemActionRecommendation::kClampSpeed) {
181	    cmd.linear_x_mps = std::clamp(cmd.linear_x_mps, -0.2, 0.2);
182	  }
183	
184	  auto decision = gate_->Evaluate(cmd);
185	  last_decision_ = decision;
186	
187	  geometry_msgs::msg::Twist safe_cmd;
188	  safe_cmd.linear.x = decision.linear_x_mps;
189	  safe_cmd.linear.y = decision.linear_y_mps;
190	  safe_cmd.angular.z = decision.angular_z_radps;
191	  safe_cmd_vel_pub_->publish(safe_cmd);
192	
193	  PublishSafetyState(decision);
194	}
195	
196	void SafetyGateNode::PublishIdleSafetyState() {
197	  // 无任何运动指令时构造零速裁决：allowed 由多源健康聚合决定，
198	  // reason 标注 idle 以便运维区分"门控放行"与"门控阻断"。
199	  amr_dispatcher_core::safety::CmdVelGateDecision idle;
200	  const bool effective_estop = estop_active_ || auto_fault_latched_;
201	  idle.allowed = watchdog_ok_ && !effective_estop && !bumper_active_ && !manual_takeover_active_;
202	  idle.reason = idle.allowed ? "idle" : "idle_blocked";
203	  idle.severity = effective_estop || bumper_active_ ? amr_dispatcher_core::safety::SafetySeverity::kCritical
204	                                                 : (watchdog_ok_ ? amr_dispatcher_core::safety::SafetySeverity::kInfo
205	                                                                 : amr_dispatcher_core::safety::SafetySeverity::kWarn);
206	  PublishSafetyState(idle);
207	}
208	
209	void SafetyGateNode::PublishSafetyState(const amr_dispatcher_core::safety::CmdVelGateDecision& decision) {
210	  amr_dispatcher_interfaces::msg::SafetyState state_msg;
211	  state_msg.header.stamp = now();
212	  state_msg.motion_allowed = decision.allowed;
213	  state_msg.reason = decision.reason;
214	
215	  if (decision.severity == amr_dispatcher_core::safety::SafetySeverity::kCritical) {
216	    state_msg.severity = "CRITICAL";
217	    state_msg.speed_scale = 0.0;
218	  } else if (decision.severity == amr_dispatcher_core::safety::SafetySeverity::kWarn) {
219	    state_msg.severity = "WARN";
220	    state_msg.speed_scale = 0.3;
221	  } else {
222	    state_msg.severity = "INFO";
223	    state_msg.speed_scale = 1.0;
224	  }
225	
226	  if (estop_active_ || auto_fault_latched_) state_msg.active_sources.push_back("estop");
227	  if (bumper_active_) state_msg.active_sources.push_back("bumper");
228	  if (manual_takeover_active_) state_msg.active_sources.push_back("manual_takeover");
229	  if (!state_msg.active_sources.empty()) {
230	    state_msg.active_stop_source = state_msg.active_sources.front();
231	  }
232	
233	  safety_state_pub_->publish(state_msg);
234	}
235	
236	}  // namespace amr_dispatcher_ros
237	
238	int main(int argc, char* argv[]) {
239	  rclcpp::init(argc, argv);
240	  auto node = std::make_shared<amr_dispatcher_ros::SafetyGateNode>();
241	  rclcpp::spin(node);
242	  rclcpp::shutdown();
243	  return 0;
244	}
