148	void NavigateSequenceBridgeNode::TrackingErrorCb(
149	    const amr_dispatcher_interfaces::msg::TrackingError::SharedPtr msg) {
150	  if (!msg->arrived || use_nav2_) {
151	    return;  // Nav2 模式由 navigate_to_pose 的结果驱动，不消费 /tracking/error
152	  }
153	  if (!current_goal_ || !waiting_arrival_) {
154	    return;  // 与本桥当前航点无关的到达信号（如 dispatcher 自己的 /plan 链）直接忽略
155	  }
156	  waiting_arrival_ = false;
157	  PublishSeqFeedback("AT_STATION", 0.0);
158	  RCLCPP_INFO(get_logger(), "Waypoint %zu/%zu reached (station=%s)", current_index_ + 1,
159	              nav_poses_.size(),
160	              current_index_ < station_names_.size() ? station_names_[current_index_].c_str()
161	                                                     : "-");
162	  AdvanceAfterArrival();
163	}
164	
165	void NavigateSequenceBridgeNode::AdvanceAfterArrival() {
166	  if (!current_goal_) {
167	    return;
168	  }
169	  completed_waypoints_++;
170	  current_index_++;
171	  if (current_index_ >= nav_poses_.size()) {
172	    if (loop_) {
173	      current_index_ = 0;
174	      RCLCPP_INFO(get_logger(), "Loop: sequence finished (%d waypoint(s) total), restarting from 0",
175	                  completed_waypoints_);
176	    } else {
177	      auto result = std::make_shared<NavigateSequence::Result>();
178	      result->success = true;
179	      result->message = "all waypoints reached";
180	      result->completed_waypoints = completed_waypoints_;
181	      result->failed_waypoints = failed_waypoints_;
182	      current_goal_->succeed(result);
183	      current_goal_.reset();
184	      waiting_arrival_ = false;
185	      nav2_pending_ = false;
186	      RCLCPP_INFO(get_logger(),
187	                  "NavigateSequence goal succeeded: %d waypoint(s) completed, %d failed",
188	                  completed_waypoints_, failed_waypoints_);
189	      return;
190	    }
191	  }
192	  if (use_nav2_) {
193	#ifdef AMR_HAVE_NAV2_MSGS
194	    SendNav2GoalForCurrentIndex();
195	#endif
196	  } else {
197	    PublishCurrentWaypoint();
198	  }
199	}
200	
201	void NavigateSequenceBridgeNode::PublishSeqFeedback(const std::string& state,
202	                                                    double distance_m) {
203	  if (!current_goal_ || !current_goal_->is_active()) {
204	    return;
205	  }
206	  auto fb = std::make_shared<NavigateSequence::Feedback>();
207	  fb->current_index = static_cast<std::int32_t>(current_index_);
208	  fb->total_waypoints = static_cast<std::int32_t>(nav_poses_.size());
209	  fb->current_station =
210	      current_index_ < station_names_.size() ? station_names_[current_index_] : std::string{};
211	  fb->state = state;
212	  fb->distance_to_current_goal_m = distance_m;
213	  current_goal_->publish_feedback(fb);
214	}
215	
216	void NavigateSequenceBridgeNode::StopFallbackMotion() {
217	  if (use_nav2_ || !plan_pub_) {
218	    return;  // Nav2 模式没有 /plan 链，无需空路径停车
219	  }
220	  nav_msgs::msg::Path empty;
221	  empty.header.stamp = now();
222	  empty.header.frame_id = "map";
223	  plan_pub_->publish(empty);
224	  RCLCPP_INFO(get_logger(), "Published empty %s to stop fallback motion", plan_topic_.c_str());
225	}
226	
227	void NavigateSequenceBridgeNode::CancelPollTick() {
228	  if (!current_goal_ || !current_goal_->is_canceling()) {
229	    return;
230	  }
231	#ifdef AMR_HAVE_NAV2_MSGS
232	  if (use_nav2_ && nav2_client_) {
233	    // cancel 级联：本 goal 取消时同步取消 Nav2 全部在途 goal
234	    nav2_client_->async_cancel_all_goals();
235	  }
236	#endif
237	  // fallback 运动中被取消：发空 /plan 停车，否则 path_tracker 继续追旧航点（审查 I3）
238	  StopFallbackMotion();
239	  auto result = std::make_shared<NavigateSequence::Result>();
240	  result->success = false;
241	  result->message = "canceled by client";
242	  result->completed_waypoints = completed_waypoints_;
243	  result->failed_waypoints = failed_waypoints_;
244	  current_goal_->canceled(result);
245	  current_goal_.reset();
246	  waiting_arrival_ = false;
247	  nav2_pending_ = false;
248	  RCLCPP_INFO(get_logger(), "NavigateSequence goal canceled (%d waypoint(s) completed)",
249	              completed_waypoints_);
250	}
251	
252	#ifdef AMR_HAVE_NAV2_MSGS
253	void NavigateSequenceBridgeNode::SendNav2GoalForCurrentIndex() {
254	  if (!current_goal_ || current_index_ >= nav_poses_.size()) {
255	    return;
256	  }
257	  if (!nav2_client_ || !nav2_client_->action_server_is_ready()) {
258	    // 单点失败 -> 整 goal abort
259	    failed_waypoints_++;
260	    auto result = std::make_shared<NavigateSequence::Result>();
261	    result->success = false;
262	    result->message = "nav2 action server not available: " + nav2_action_name_;
263	    result->completed_waypoints = completed_waypoints_;
264	    result->failed_waypoints = failed_waypoints_;
265	    RCLCPP_ERROR(get_logger(), "%s (waypoint %zu/%zu)", result->message.c_str(),
266	                 current_index_ + 1, nav_poses_.size());
267	    StopFallbackMotion();  // 终结路径统一停车（use_nav2_ 下为空操作）
268	    current_goal_->abort(result);
269	    current_goal_.reset();
270	    waiting_arrival_ = false;
271	    nav2_pending_ = false;
272	    return;
273	  }
274	
275	  nav2_msgs::action::NavigateToPose::Goal nav_goal;
276	  nav_goal.pose = nav_poses_[current_index_];
277	  nav_goal.pose.header.stamp = now();
278	  nav2_pending_ = true;
279	  const std::weak_ptr<GoalHandleNavSeq> seq_goal = current_goal_;
280	
281	  rclcpp_action::Client<nav2_msgs::action::NavigateToPose>::SendGoalOptions opts;
282	  opts.feedback_callback =
283	      [this, seq_goal](const rclcpp_action::ClientGoalHandle<nav2_msgs::action::NavigateToPose>::SharedPtr& gh,
284	                       const std::shared_ptr<const nav2_msgs::action::NavigateToPose::Feedback>& fb) {
285	        Nav2FeedbackCb(gh, fb, seq_goal);
286	      };
287	  opts.result_callback =
288	      [this, seq_goal](const rclcpp_action::ClientGoalHandle<nav2_msgs::action::NavigateToPose>::WrappedResult& result) {
289	        Nav2ResultCb(result, seq_goal);
290	      };
291	  nav2_client_->async_send_goal(nav_goal, opts);
292	  PublishSeqFeedback("NAVIGATING", 0.0);
293	  RCLCPP_INFO(get_logger(), "Sending waypoint %zu/%zu to %s", current_index_ + 1,
294	              nav_poses_.size(), nav2_action_name_.c_str());
295	}
296	
297	void NavigateSequenceBridgeNode::Nav2FeedbackCb(
298	    const rclcpp_action::ClientGoalHandle<nav2_msgs::action::NavigateToPose>::SharedPtr& /*gh*/,
299	    const std::shared_ptr<const nav2_msgs::action::NavigateToPose::Feedback>& fb,
300	    const std::weak_ptr<GoalHandleNavSeq>& seq_goal) {
301	  // 身份校验：只处理仍属于当前 NavigateSequence goal 的在途反馈
302	  const auto locked = seq_goal.lock();
303	  if (!locked || locked != current_goal_ || !nav2_pending_) {
304	    return;
305	  }
306	  PublishSeqFeedback("NAVIGATING", fb ? static_cast<double>(fb->feedback.distance_remaining) : 0.0);
307	}
308	
309	void NavigateSequenceBridgeNode::Nav2ResultCb(
310	    const rclcpp_action::ClientGoalHandle<nav2_msgs::action::NavigateToPose>::WrappedResult& result,
311	    const std::weak_ptr<GoalHandleNavSeq>& seq_goal) {
312	  const auto locked = seq_goal.lock();
313	  if (!locked || locked != current_goal_ || !nav2_pending_) {
314	    return;  // 已被 cancel 终结 / 已换 goal：丢弃过期结果
315	  }
316	  nav2_pending_ = false;
317	  if (result.code == rclcpp_action::ResultCode::SUCCEEDED && result.result &&
318	      result.result->success) {
319	    PublishSeqFeedback("AT_STATION", 0.0);
320	    AdvanceAfterArrival();
321	    return;
322	  }
323	  // 单点失败 -> 整 goal abort
324	  failed_waypoints_++;
325	  auto res = std::make_shared<NavigateSequence::Result>();
326	  res->success = false;
327	  res->message = "navigate_to_pose failed at waypoint " + std::to_string(current_index_ + 1);
328	  res->completed_waypoints = completed_waypoints_;
329	  res->failed_waypoints = failed_waypoints_;
330	  RCLCPP_ERROR(get_logger(), "%s (code=%d)", res->message.c_str(),
331	               static_cast<int>(result.code));
332	  StopFallbackMotion();  // 终结路径统一停车（use_nav2_ 下为空操作）
333	  current_goal_->abort(res);
334	  current_goal_.reset();
335	  waiting_arrival_ = false;
336	}
337	#endif  // AMR_HAVE_NAV2_MSGS
338	
339	}  // namespace amr_dispatcher_ros
340	
341	int main(int argc, char* argv[]) {
342	  rclcpp::init(argc, argv);
343	  auto node = std::make_shared<amr_dispatcher_ros::NavigateSequenceBridgeNode>();
344	  rclcpp::spin(node);
345	  rclcpp::shutdown();
346	  return 0;
347	}
