103	void SafetyGateNode::EstopCallback(const std_msgs::msg::Bool::SharedPtr msg) {
104	  estop_active_ = msg->data;
105	  if (estop_active_) {
106	    amr_dispatcher_core::safety::SafetyEvent evt;
107	    evt.source = "estop";
108	    evt.severity = amr_dispatcher_core::safety::SafetySeverity::kCritical;
109	    evt.message = "Emergency stop button pressed";
