#include <string>
#include <vector>

#include "amr_dispatcher_core/config/config_loader.hpp"

namespace amr_dispatcher_core::catalog {

struct Station {
  std::string id;
  std::string frame_id = "map";
  double x = 0.0;
  double y = 0.0;
  double yaw = 0.0;
};

struct CatalogStationEdge {
  std::string from;
  std::string to;
  double distance_m = 0.0;
  bool bidirectional = true;
  bool enabled = true;
};

struct StationCatalog {
  std::vector<Station> stations;
  std::vector<CatalogStationEdge> edges;
};

struct StationListProjection {
  std::vector<std::string> station_ids;
  std::vector<std::string> frame_ids;
  std::vector<double> x;
  std::vector<double> y;
  std::vector<double> yaw;
  std::string message;
};

struct StationRouteListProjection {
  std::vector<std::string> from_station;
  std::vector<std::string> to_station;
  std::vector<double> distance_m;
  std::vector<bool> bidirectional;
  std::vector<bool> enabled;
  std::string message;
};

std::optional<StationCatalog> LoadStationCatalog(const std::filesystem::path& path);
const Station* FindStation(const StationCatalog& catalog, const std::string& id);
std::optional<double> EstimateRouteDistance(
    const StationCatalog& catalog, const std::string& from, const std::string& to);
std::optional<std::vector<std::string>> FindRoutePath(
    const StationCatalog& catalog, const std::string& from, const std::string& to);
bool ValidateStationCatalog(const StationCatalog& catalog, std::string* message);
StationListProjection BuildStationListProjection(const StationCatalog& catalog);
StationRouteListProjection BuildStationRouteListProjection(const StationCatalog& catalog);

// 站点目录热重载器：构造时加载初始目录，Tick 按文件 mtime 变化重载；
// 新目录校验失败时保留旧目录（不清空），错误经 last_error 暴露。
class StationCatalogReloader {
 public:
  explicit StationCatalogReloader(std::filesystem::path path);

  // 驱动一次 mtime 检查；返回本次是否完成换新。
  bool Tick();

  const StationCatalog& catalog() const { return catalog_; }
  bool loaded() const { return loaded_; }
  std::string last_error() const;

 private:
  void TryLoad(bool count_as_reload);

  std::filesystem::path path_;
  StationCatalog catalog_{};
  bool loaded_ = false;
  std::size_t reload_count_ = 0;
  std::string last_error_;
  config::HotReloadWatcher watcher_;
};

}  // namespace amr_dispatcher_core::catalog

#include "amr_dispatcher_core/safety/cmd_vel_gate.hpp"

#include <algorithm>
#include <cmath>
#include <utility>

namespace amr_dispatcher_core::safety {

CmdVelGate::CmdVelGate(CmdVelGateConfig config) : config_(std::move(config)) {}

void CmdVelGate::PushEvent(SafetyEvent event) {
  recent_events_.push_back(std::move(event));
  if (recent_events_.size() > config_.event_history_capacity) {
    recent_events_.erase(recent_events_.begin());
  }
}

void CmdVelGate::ClearEvents() { recent_events_.clear(); }

namespace {

double Scale(double value, double max_abs) {
  // 非有限值兜底：NaN 属于无效指令直接归零；±Inf 视为超限走下方钳位
  if (std::isnan(value)) return 0.0;
  if (std::abs(value) <= max_abs) return value;
  return (value > 0 ? max_abs : -max_abs);
}

}  // namespace

CmdVelGateDecision CmdVelGate::Evaluate(const CmdVelCommand& command,
                                        std::chrono::steady_clock::time_point now) const {
  CmdVelGateDecision decision;
  decision.linear_x_mps = command.linear_x_mps;
  decision.linear_y_mps = command.linear_y_mps;
  decision.angular_z_radps = command.angular_z_radps;
  decision.allowed = true;

  // 1) 上限缩放
  decision.linear_x_mps = Scale(decision.linear_x_mps, config_.max_linear_x_mps);
  decision.linear_y_mps = Scale(decision.linear_y_mps, config_.max_linear_y_mps);
  decision.angular_z_radps = Scale(decision.angular_z_radps, config_.max_angular_z_radps);

  // 2) 多源阻止：critical 事件 → 全停；warn → 缩放至 0.3 倍
  // 事件带 TTL：超过 stamp + event_ttl 的历史事件视为已解除，不再影响当前决策
  bool critical = false;
  bool warned = false;
  std::string critical_reason;
  for (const auto& e : recent_events_) {
    if (now - e.stamp > config_.event_ttl) {
      continue;  // 事件已过期
    }
    if (e.severity == SafetySeverity::kCritical) {
      if (config_.source_blocked && config_.source_blocked(e.source)) {
        critical = true;
        critical_reason = e.source + ": " + e.message;
      }
    } else if (e.severity == SafetySeverity::kWarn) {
      warned = true;
    }
  }

  if (critical) {
    decision.allowed = false;
    decision.linear_x_mps = 0.0;
    decision.linear_y_mps = 0.0;
    decision.angular_z_radps = 0.0;
    decision.reason = critical_reason;
    decision.severity = SafetySeverity::kCritical;
    return decision;
  }
  if (warned) {
    decision.linear_x_mps *= 0.3;
    decision.linear_y_mps *= 0.3;
    decision.angular_z_radps *= 0.3;
    decision.severity = SafetySeverity::kWarn;
    decision.reason = "warn active: reducing to 30%";
  }
  return decision;
}

}  // namespace amr_dispatcher_core::safety

#pragma once

#include <chrono>
#include <cstddef>
#include <functional>
#include <string>
#include <vector>

namespace amr_dispatcher_core::safety {

enum class SafetySeverity { kInfo, kWarn, kCritical };

struct SafetyEvent {
  std::string source;
  SafetySeverity severity = SafetySeverity::kInfo;
  std::string message;
  std::chrono::steady_clock::time_point stamp = std::chrono::steady_clock::now();
};

struct CmdVelCommand {
  double linear_x_mps = 0.0;
  double linear_y_mps = 0.0;
  double angular_z_radps = 0.0;
  std::chrono::steady_clock::time_point stamp = std::chrono::steady_clock::now();
};

struct CmdVelGateDecision {
  double linear_x_mps = 0.0;
  double linear_y_mps = 0.0;
  double angular_z_radps = 0.0;
  bool allowed = true;
  std::string reason;
  SafetySeverity severity = SafetySeverity::kInfo;
};

// cmd_vel_gate 配置：上游源（bumper / estop / ...）通过 source_blocked 回调告知是否激活阻止
struct CmdVelGateConfig {
  double max_linear_x_mps = 1.5;
  double max_linear_y_mps = 1.0;
  double max_angular_z_radps = 2.0;
  std::function<bool(const std::string&)> source_blocked;
  std::size_t event_history_capacity = 256;
  // 事件 TTL：Evaluate 时刻超过 stamp + event_ttl 的事件视为已失效，不再触发阻止/降速
  std::chrono::milliseconds event_ttl{std::chrono::milliseconds(2000)};
};

class CmdVelGate {
 public:
  explicit CmdVelGate(CmdVelGateConfig config = {});

  void PushEvent(SafetyEvent event);
  void ClearEvents();

  // now 用于事件 TTL 判定；默认取当前时刻（与旧行为兼容）
  CmdVelGateDecision Evaluate(
      const CmdVelCommand& command,
      std::chrono::steady_clock::time_point now = std::chrono::steady_clock::now()) const;

  const std::vector<SafetyEvent>& recent_events() const { return recent_events_; }

 private:
  CmdVelGateConfig config_;
  std::vector<SafetyEvent> recent_events_;
};

}  // namespace amr_dispatcher_core::safety

#include "amr_dispatcher_core/safety/cmd_vel_gate.hpp"

#include <gtest/gtest.h>

#include <cmath>
#include <limits>

using namespace amr_dispatcher_core::safety;
using namespace std::chrono_literals;

TEST(CmdVelGateTest, AllowsCmdUnderLimits) {
  CmdVelGate gate{};
  CmdVelCommand cmd{.linear_x_mps = 0.5, .linear_y_mps = 0.3, .angular_z_radps = 0.4};
  const auto d = gate.Evaluate(cmd);
  EXPECT_TRUE(d.allowed);
  EXPECT_NEAR(d.linear_x_mps, 0.5, 1e-9);
  EXPECT_EQ(d.severity, SafetySeverity::kInfo);
}

TEST(CmdVelGateTest, ClampsOverSpeed) {
  CmdVelGate gate{};
  CmdVelCommand cmd{.linear_x_mps = 5.0, .linear_y_mps = 0.0, .angular_z_radps = 5.0};
  const auto d = gate.Evaluate(cmd);
  EXPECT_DOUBLE_EQ(d.linear_x_mps, 1.5);
  EXPECT_DOUBLE_EQ(d.angular_z_radps, 2.0);
}

TEST(CmdVelGateTest, CriticalEventStopsMotion) {
  CmdVelGate gate({.source_blocked = [](const std::string& src) {
    return src == "bumper";
  }});
  gate.PushEvent({"bumper", SafetySeverity::kCritical, "front bumper hit"});
  CmdVelCommand cmd{.linear_x_mps = 0.5};
  const auto d = gate.Evaluate(cmd);
  EXPECT_FALSE(d.allowed);
  EXPECT_DOUBLE_EQ(d.linear_x_mps, 0.0);
  EXPECT_EQ(d.severity, SafetySeverity::kCritical);
  EXPECT_NE(d.reason.find("bumper"), std::string::npos);
}

TEST(CmdVelGateTest, WarnEventReducesSpeed) {
  CmdVelGate gate{};
  gate.PushEvent({"battery", SafetySeverity::kWarn, "low"});
  const auto d = gate.Evaluate({.linear_x_mps = 1.0});
  EXPECT_TRUE(d.allowed);
  EXPECT_NEAR(d.linear_x_mps, 0.3, 1e-9);
  EXPECT_EQ(d.severity, SafetySeverity::kWarn);
}

TEST(CmdVelGateTest, CriticalWithoutSourceBlockIgnored) {
  CmdVelGate gate{};  // 没有 source_blocked 回调
  gate.PushEvent({"estop", SafetySeverity::kCritical, "pressed"});
  const auto d = gate.Evaluate({.linear_x_mps = 0.5});
  EXPECT_TRUE(d.allowed);
  EXPECT_NEAR(d.linear_x_mps, 0.5, 1e-9);
}

TEST(CmdVelGateTest, EventHistoryBounded) {
  CmdVelGate gate({.event_history_capacity = 3});
  for (int i = 0; i < 10; ++i) {
    gate.PushEvent({"x", SafetySeverity::kInfo, "m" + std::to_string(i)});
  }
  EXPECT_EQ(gate.recent_events().size(), 3u);
  EXPECT_EQ(gate.recent_events().back().message, "m9");
}

TEST(CmdVelGateTest, ClearEvents) {
  CmdVelGate gate{};
  gate.PushEvent({"a", SafetySeverity::kWarn, "x"});
  gate.ClearEvents();
  EXPECT_TRUE(gate.recent_events().empty());
}

// A1：critical 事件在 stamp + event_ttl 内保持阻止，超过 TTL 后自动放行
TEST(CmdVelGateTest, CriticalEventExpiresAfterTtl) {
  CmdVelGate gate({.source_blocked = [](const std::string& src) {
    return src == "bumper";
  }});
  const auto stamp = std::chrono::steady_clock::now();
  gate.PushEvent({"bumper", SafetySeverity::kCritical, "front bumper hit", stamp});
  const CmdVelCommand cmd{.linear_x_mps = 0.5};

  // TTL 内（默认 2000ms）仍然阻止
  const auto within = gate.Evaluate(cmd, stamp + 1500ms);
  EXPECT_FALSE(within.allowed);
  EXPECT_EQ(within.severity, SafetySeverity::kCritical);

  // 超过 TTL 后事件失效，正常放行
  const auto after = gate.Evaluate(cmd, stamp + 2000ms + 1ms);
  EXPECT_TRUE(after.allowed);
  EXPECT_NEAR(after.linear_x_mps, 0.5, 1e-9);
}

// A1：warn 事件同样受 TTL 约束（超时后不再降速）
TEST(CmdVelGateTest, WarnEventExpiresAfterTtl) {
  CmdVelGate gate{};
  const auto stamp = std::chrono::steady_clock::now();
  gate.PushEvent({"battery", SafetySeverity::kWarn, "low", stamp});
  const auto after = gate.Evaluate({.linear_x_mps = 1.0}, stamp + 2000ms + 1ms);
  EXPECT_TRUE(after.allowed);
  EXPECT_DOUBLE_EQ(after.linear_x_mps, 1.0);
  EXPECT_EQ(after.severity, SafetySeverity::kInfo);
}

// A1：NaN 指令归零，避免把非法值写进底盘
TEST(CmdVelGateTest, ScaleNanBecomesZero) {
  CmdVelGate gate{};
  const auto d = gate.Evaluate({.linear_x_mps = std::numeric_limits<double>::quiet_NaN(),
                                .linear_y_mps = std::numeric_limits<double>::quiet_NaN(),
                                .angular_z_radps = std::numeric_limits<double>::quiet_NaN()});
  EXPECT_TRUE(d.allowed);
  EXPECT_TRUE(std::isfinite(d.linear_x_mps));
  EXPECT_DOUBLE_EQ(d.linear_x_mps, 0.0);
  EXPECT_DOUBLE_EQ(d.linear_y_mps, 0.0);
  EXPECT_DOUBLE_EQ(d.angular_z_radps, 0.0);
}

// A1：±Inf 按超限钳到 ±max（不放行非法值，也不直接归零）
TEST(CmdVelGateTest, ScaleInfClampsToLimit) {
  CmdVelGate gate{};
  const auto d = gate.Evaluate(
      {.linear_x_mps = std::numeric_limits<double>::infinity(),
       .angular_z_radps = -std::numeric_limits<double>::infinity()});
  EXPECT_TRUE(d.allowed);
  EXPECT_DOUBLE_EQ(d.linear_x_mps, 1.5);
  EXPECT_DOUBLE_EQ(d.angular_z_radps, -2.0);
}

