88	  err_msg.controller_name = controller_type_;
89	
90	  if (controller_type_ == "stanley") {
91	    auto res = stanley_controller_->Compute(current_pose_);
92	    cmd.linear.x = res.cmd.linear_x;
93	    cmd.angular.z = res.cmd.angular_z;
94	
95	    err_msg.lateral_error_m = res.lateral_error;
96	    err_msg.heading_error_rad = res.heading_error;
97	    err_msg.target_linear_x_mps = res.cmd.linear_x;
98	    err_msg.target_angular_z_radps = res.cmd.angular_z;
99	    err_msg.actual_linear_x_mps = current_linear_speed_;
100	    err_msg.nearest_waypoint_index = static_cast<int32_t>(res.nearest_index);
101	    err_msg.arrived = res.goal_reached;
102	  } else {
103	    auto res = pp_controller_->Compute(current_pose_);
104	    cmd.linear.x = res.cmd.linear_x;
105	    cmd.angular.z = res.cmd.angular_z;
106	
107	    err_msg.lateral_error_m = res.lateral_error;
108	    err_msg.heading_error_rad = res.heading_error;
109	    err_msg.target_linear_x_mps = res.cmd.linear_x;
110	    err_msg.target_angular_z_radps = res.cmd.angular_z;
111	    err_msg.actual_linear_x_mps = current_linear_speed_;
112	    err_msg.nearest_waypoint_index = static_cast<int32_t>(res.nearest_index);
113	    err_msg.arrived = res.goal_reached;
114	  }
115	
116	  cmd_vel_pub_->publish(cmd);
117	  error_pub_->publish(err_msg);
118	
119	  if (heartbeat_pub_) {
120	    std_msgs::msg::Bool hb;
121	    hb.data = true;
122	    heartbeat_pub_->publish(hb);
