119	    evt.source = "bumper";
120	    evt.severity = amr_dispatcher_core::safety::SafetySeverity::kCritical;
121	    evt.message = "Front bumper triggered collision";
122	    gate_->PushEvent(evt);
123	    RCLCPP_ERROR(get_logger(), "BUMPER TRIGGERED");
124	  }
125	}
