459	void DispatcherNode::EnqueueMissionCb(
460	    const std::shared_ptr<amr_dispatcher_interfaces::srv::EnqueueMission::Request> req,
461	    std::shared_ptr<amr_dispatcher_interfaces::srv::EnqueueMission::Response> resp) {
462	  if (!queue_) {
463	    resp->success = false;
464	    resp->message = "Dispatcher unconfigured";
465	    resp->queue_size = 0;
466	    return;
467	  }
468	  amr_dispatcher_core::dispatcher::Mission m;
469	  m.id = "m_" + std::to_string(next_sequence_++);
470	  m.order_id = req->mission_file;
471	  m.priority = req->priority;
472	  m.sequence = next_sequence_;
473	  m.state = amr_dispatcher_core::dispatcher::MissionState::kPending;
474	  auto push_res = queue_->Push(m);
475	  resp->success = push_res.accepted;
476	  resp->message = push_res.accepted ? "Mission enqueued: " + m.id : push_res.message;
477	  resp->queue_size = static_cast<int32_t>(queue_->size());
478	
479	  if (push_res.accepted) {
480	    // 启动决策走 queued_mission_start 行为树（start_if_idle 且当前空闲才立即启动）
481	    amr_dispatcher_bt::QueuedMissionStartBehaviorTreeInput start_input;
482	    start_input.request.start_if_idle = req->start_if_idle;
483	    start_input.request.mission_active = !tracking_mission_id_.empty();
484	    const auto start_bt = amr_dispatcher_bt::TickQueuedMissionStartBehaviorTree(start_input);
485	    if (start_bt.success && start_bt.decision.request_queue_start) {
486	      queue_start_requested_ = true;
487	    }
