493	void DispatcherNode::CancelQueuedMissionCb(
494	    const std::shared_ptr<amr_dispatcher_interfaces::srv::CancelQueuedMission::Request> req,
495	    std::shared_ptr<amr_dispatcher_interfaces::srv::CancelQueuedMission::Response> resp) {
496	  if (!queue_) {
497	    resp->success = false;
498	    resp->message = "Dispatcher unconfigured";
499	    resp->queue_size = 0;
500	    return;
501	  }
502	  bool canceled = queue_->Cancel(req->mission_id);
503	  if (canceled) {
504	    // 排队取消命中：收口该任务的 action goal/handle 预占/pending_nav（审查 I5）
505	    CleanupMissionCancel(req->mission_id, "mission canceled by operator");
506	  } else {
507	    // 按整单取消：取消前取证该订单在队任务，取消成功后逐个收口（审查 I5）
508	    std::vector<std::string> action_mission_ids;
509	    if (!execute_goal_handles_.empty()) {
510	      for (const auto& qm : queue_->Snapshot()) {
511	        if (qm.order_id == req->mission_id) {
512	          action_mission_ids.push_back(qm.id);
513	        }
514	      }
515	    }
516	    const std::size_t order_count = queue_->CancelOrder(req->mission_id);
517	    canceled = (order_count > 0);
518	    for (const auto& id : action_mission_ids) {
519	      CleanupMissionCancel(id, "mission canceled by operator");
520	    }
521	  }
522	  if (req->cancel_active) {
523	    bool erased = false;
524	    {
525	      std::lock_guard<std::mutex> lock(active_missions_mutex_);
526	      erased = (active_missions_.erase(req->mission_id) > 0);
527	    }
528	    if (erased) {
529	      canceled = true;
530	      if (reservation_table_) {
531	        reservation_table_->Release(req->mission_id);
532	      }
533	      // 若被取消的是正在跟踪 /plan 的任务，发空路径停车
534	      if (tracking_mission_id_ == req->mission_id) {
535	        tracking_mission_id_.clear();
536	        if (plan_pub_ && plan_pub_->is_activated()) {
537	          nav_msgs::msg::Path empty;
538	          empty.header.stamp = now();
539	          empty.header.frame_id = "map";
540	          plan_pub_->publish(empty);
541	        }
542	      }
543	      // 活动任务取消同样收口 action goal 与在途导航 goal（cancel_active 路径，审查 I5）
544	      CleanupMissionCancel(req->mission_id, "mission canceled by operator");
545	    }
546	  }
547	  resp->success = canceled;
548	  resp->message = canceled ? "Mission canceled: " + req->mission_id : "Mission not found: " + req->mission_id;
549	  resp->queue_size = static_cast<int32_t>(queue_->size());
550	}
