55	void PathTrackerNode::PathCallback(const nav_msgs::msg::Path::SharedPtr msg) {
56	  waypoints_.clear();
57	  for (const auto& pose_stamped : msg->poses) {
58	    amr_dispatcher_core::path_tracking::Pose2D wp;
59	    wp.x = pose_stamped.pose.position.x;
60	    wp.y = pose_stamped.pose.position.y;
61	    wp.yaw = amr_dispatcher_core::path_tracking::YawFromQuaternion(
62	        pose_stamped.pose.orientation.z, pose_stamped.pose.orientation.w);
63	    waypoints_.push_back(wp);
64	  }
65	  has_path_ = !waypoints_.empty();
66	  if (pp_controller_) pp_controller_->SetPath(waypoints_);
67	  if (stanley_controller_) stanley_controller_->SetPath(waypoints_);
68	  RCLCPP_INFO(get_logger(), "Received path with %zu waypoints", waypoints_.size());
69	}
