552	void DispatcherNode::PreemptMissionCb(
553	    const std::shared_ptr<amr_dispatcher_interfaces::srv::PreemptMission::Request> req,
554	    std::shared_ptr<amr_dispatcher_interfaces::srv::PreemptMission::Response> resp) {
555	  if (!queue_) {
556	    resp->success = false;
557	    resp->message = "Dispatcher unconfigured";
558	    resp->queue_size = 0;
559	    return;
560	  }
561	  amr_dispatcher_core::dispatcher::Mission m;
562	  m.id = "preempt_" + std::to_string(next_sequence_++);
563	  m.order_id = req->mission_file;
564	  m.priority = req->priority > 100 ? req->priority : 100;
565	  m.sequence = next_sequence_;
566	  m.state = amr_dispatcher_core::dispatcher::MissionState::kPending;
567	  auto push_res = queue_->Push(m);
568	  resp->success = push_res.accepted;
569	  resp->mission_id = m.id;
570	  resp->message = push_res.accepted ? "Preempt mission queued: " + m.id : push_res.message;
