752	rclcpp_action::CancelResponse DispatcherNode::HandleCancel(
753	    const std::shared_ptr<GoalHandleExecute> goal_handle) {
754	  if (execute_goal_handles_.find(goal_handle->get_goal()->mission_id) ==
755	      execute_goal_handles_.end()) {
756	    return rclcpp_action::CancelResponse::REJECT;
757	  }
758	  // 只受理取消请求：rclcpp_action 在本回调返回 ACCEPT 之后才把 goal 迁移到
759	  // CANCELING，而 canceled() 只允许在 CANCELING 态调用——
760	  // 实际的任务取消与 goal 终结延后到 ProcessActionCancels（ScheduleTick 内）。
761	  return rclcpp_action::CancelResponse::ACCEPT;
762	}
763	
764	void DispatcherNode::HandleAccepted(const std::shared_ptr<GoalHandleExecute> goal_handle) {
765	  const auto goal = goal_handle->get_goal();
766	  // ACCEPTED -> EXECUTING：后续 publish_feedback/succeed/abort 的前置条件
767	  goal_handle->execute();
768	
769	  if (!queue_) {
770	    if (reservation_table_) {
771	      reservation_table_->Release(goal->mission_id);
772	    }
773	    auto result = std::make_shared<ExecuteMission::Result>();
774	    result->success = false;
775	    result->error_code = 1;
776	    result->message = "dispatcher not configured";
777	    goal_handle->abort(result);
778	    return;
779	  }
780	
781	  amr_dispatcher_core::dispatcher::Mission m;
782	  m.id = goal->mission_id;
783	  m.order_id = goal->mission_id;  // 订单号=任务号，保证整单取消可寻址
784	  m.priority = goal->priority;
785	  m.dropoff_station = goal->target_station;
786	  if (goal->deadline_seconds > 0.0) {
787	    m.deadline_unix_ms =
788	        std::chrono::duration_cast<std::chrono::milliseconds>(
789	            std::chrono::system_clock::now().time_since_epoch())
790	            .count() +
791	        static_cast<std::int64_t>(goal->deadline_seconds * 1000.0);
792	  }
793	  m.state = amr_dispatcher_core::dispatcher::MissionState::kPending;
794	  m.sequence = next_sequence_++;
795	
796	  auto push = queue_->Push(m);
797	  if (!push.accepted) {
798	    // 入队失败回滚 HandleGoal 的资源预占并 abort（死锁风险下的显式失败出口）
799	    if (reservation_table_) {
800	      reservation_table_->Release(m.id);
801	    }
802	    auto result = std::make_shared<ExecuteMission::Result>();
803	    result->success = false;
804	    result->error_code = 1;
805	    result->message = "enqueue rejected: " + push.message;
806	    goal_handle->abort(result);
807	    RCLCPP_WARN(get_logger(), "ExecuteMission enqueue rejected for %s: %s", m.id.c_str(),
808	                push.message.c_str());
809	    return;
810	  }
811	
812	  execute_goal_handles_[m.id] = goal_handle;
813	  queue_start_requested_ = true;  // action 提交的任务武装 runtime 出队启动请求
814	  RCLCPP_INFO(get_logger(),
815	              "ExecuteMission accepted: %s -> queued (target=%s, prio=%d, resources=%zu)",
816	              m.id.c_str(), m.dropoff_station.c_str(), m.priority,
817	              goal->required_resources.size());
818	}
819	
820	void DispatcherNode::FinishExecuteGoal(const std::string& mission_id, ExecuteFinish kind,
821	                                        const std::string& message, std::int32_t error_code) {
822	  auto it = execute_goal_handles_.find(mission_id);
823	  if (it == execute_goal_handles_.end()) {
824	    return;
825	  }
826	  auto handle = it->second;
827	  execute_goal_handles_.erase(it);
828	
829	  // total_duration_sec：按派发时刻计时（排队中取消等未派发场景为 0），
830	  // 计时后即遗忘时间戳，防止 map 长期驻留
831	  double duration_sec = 0.0;
832	  auto dispatch_time = mission_dispatch_time_.find(mission_id);
833	  if (dispatch_time != mission_dispatch_time_.end()) {
834	    duration_sec = std::chrono::duration<double>(
835	                       std::chrono::steady_clock::now() - dispatch_time->second)
836	                       .count();
837	    mission_dispatch_time_.erase(dispatch_time);
838	  }
839	  if (!handle || !handle->is_active()) {
840	    return;
841	  }
842	
843	  auto result = std::make_shared<ExecuteMission::Result>();
844	  result->success = (kind == ExecuteFinish::kSucceed);
845	  result->error_code = error_code;
846	  result->message = message;
847	  result->total_duration_sec = duration_sec;
848	  try {
849	    if (handle->is_canceling()) {
850	      // 已受理 action cancel：只能走 canceled()（rclcpp_action 状态机约束）
851	      handle->canceled(result);
852	    } else if (handle->is_executing()) {
853	      if (kind == ExecuteFinish::kSucceed) {
854	        handle->succeed(result);
855	      } else {
856	        // kAbort 与服务侧取消（未进入 CANCELING 无法 canceled()）降级为 abort
857	        handle->abort(result);
858	      }
859	    } else {
860	      // ACCEPTED 未执行的兜底：先 execute 再 abort，避免 rclcpp_action 状态断言
861	      handle->execute();
862	      handle->abort(result);
863	    }
864	    RCLCPP_INFO(get_logger(), "ExecuteMission goal finished: %s kind=%d (%s)",
865	                mission_id.c_str(), static_cast<int>(kind), message.c_str());
866	  } catch (const std::exception& ex) {
867	    RCLCPP_ERROR(get_logger(), "FinishExecuteGoal(%s) failed: %s", mission_id.c_str(), ex.what());
868	  }
869	}
870	
871	void DispatcherNode::CleanupMissionCancel(const std::string& mission_id,
872	                                          const std::string& reason) {
873	  // HandleGoal 预占的 required_resources 随任务取消一并释放（plan 模式无 handle 时
874	  // Release 对无锁持有者是无操作，与既有行为一致）
875	  const bool has_handle = execute_goal_handles_.count(mission_id) > 0;
876	  if (has_handle && reservation_table_) {
877	    reservation_table_->Release(mission_id);
878	  }
879	  // action 模式级联：取消在途 NavigateSequence goal 并清 pending 标记
880	  if (navigation_backend_ == "action" && pending_nav_mission_id_ == mission_id) {
881	    if (nav_client_ && pending_nav_goal_handle_) {
882	      nav_client_->async_cancel_goal(pending_nav_goal_handle_);
883	    }
884	    pending_nav_mission_id_.clear();
885	    pending_nav_goal_handle_.reset();
886	  }
887	  if (has_handle) {
888	    // 服务侧取消未受理 action cancel（handle 不在 CANCELING），降级 abort(3 PREEMPTED)
889	    // （total_duration_sec 的时间戳由 FinishExecuteGoal 计时后遗忘）
890	    FinishExecuteGoal(mission_id, ExecuteFinish::kCanceled, reason, 3);
891	  } else {
892	    mission_dispatch_time_.erase(mission_id);
893	  }
894	  ForgetMissionDispatchState(mission_id);
895	}
