1044	void DispatcherNode::ScheduleTick() {
1045	  // 已受理的 ExecuteMission action 取消需在提前返回之前处理（10Hz 延迟 ≤100ms）
1046	  ProcessActionCancels();
1047	  if (!queue_ || queue_->empty()) {
1048	    return;
1049	  }
1050	  const std::size_t max_active = get_parameter("max_active_missions").as_int();
1051	  if (active_missions_.size() >= max_active) {
1052	    return;
1053	  }
1054	
1055	  // 单车执行模型：同时只有一条 /plan 在跟踪，其余任务保持 active 等待车辆空闲
1056	  if (!tracking_mission_id_.empty()) {
1057	    return;
1058	  }
1059	
1060	  // 行为树出队派发门控：runtime 树按"空闲 + 启动请求"给派发决策，
1061	  // 未请求启动时即使队列有任务也不出队（启动请求由提单/入队/结果链武装）。
1062	  amr_dispatcher_bt::MissionRuntimeBehaviorTreeInput runtime_input;
1063	  runtime_input.tick.mission_active = !tracking_mission_id_.empty();
1064	  runtime_input.tick.queue_start_requested = queue_start_requested_;
1065	  const auto runtime_result = amr_dispatcher_bt::TickMissionRuntimeBehaviorTree(runtime_input);
1066	  if (!runtime_result.success || !runtime_result.decision.start_queued_mission) {
1067	    return;
1068	  }
1069	  queue_start_requested_ = false;  // 启动请求被本次派发消费
1070	
1071	  // Peek→Reserve→Pop（节点单线程，Peek 与 Pop 之间无竞态）：
1072	  // 先为队首任务规划路由锁并预留，成功才出队继续派发；失败则任务留在队列、
1073	  // 发 reservation_denied 事件、重新武装启动请求后本 tick 返回——既不丢任务也不违反封路。
1074	  const auto* peeked = queue_->Peek();
1075	  if (!peeked) {
1076	    return;  // 队列任务全部暂停：与 PopNext 失败等价，本 tick 结束
1077	  }
1078	  const std::string candidate_id = peeked->id;
1079	  const std::string candidate_order_id = peeked->order_id;
1080	  std::vector<std::string> route_locks;
1081	  if (catalog_reloader_ != nullptr && catalog_reloader_->loaded()) {
1082	    route_locks = amr_dispatcher_core::workflow::PlanMissionRouteLocks(
1083	        catalog_reloader_->catalog(), peeked->pickup_station, peeked->dropoff_station);
1084	  }
1085	  if (!route_locks.empty() && reservation_table_) {
1086	    auto reserve = reservation_table_->Reserve(candidate_id, route_locks);
1087	    if (!reserve.success) {
1088	      pending_wait_[candidate_id] = route_locks;  // WFG：该任务在等这批锁
1089	      RCLCPP_WARN(get_logger(), "Reservation denied for queued mission %s: %s",
1090	                  candidate_id.c_str(), reserve.message.c_str());
1091	      if (event_pub_ && event_pub_->is_activated()) {
1092	        amr_dispatcher_interfaces::msg::MissionEvent msg;
1093	        msg.stamp = now();
1094	        msg.mission_id = candidate_id;
1095	        msg.order_id = candidate_order_id;
1096	        msg.event = "reservation_denied";
1097	        msg.from_state = "PENDING";
1098	        msg.to_state = "PENDING";  // 任务留在队列，状态不变
1099	        msg.reason = reserve.message;
1100	        event_pub_->publish(msg);
1101	      }
1102	      if (event_log_) {
1103	        amr_dispatcher_core::dispatcher::MissionEvent evt;
1104	        evt.stamp = "now";
1105	        evt.mission_id = candidate_id;
1106	        evt.event = "reservation_denied";
1107	        evt.message = reserve.message;
1108	        event_log_->Append(evt);
1109	      }
1110	      ReArmQueueStartRequest();  // 队列非空 -> 稍后锁释放时重试派发
1111	      return;
1112	    }
1113	    mission_reserved_at_[candidate_id] = std::chrono::steady_clock::now();
1114	  }
1115	  pending_wait_.erase(candidate_id);  // 预留通过（或本轮无锁），历史等待记录作废
1116	
1117	  auto pop = queue_->PopNext();
1118	  if (!pop.success || !pop.mission) {
1119	    return;
1120	  }
1121	
1122	  amr_dispatcher_core::dispatcher::Mission m = *pop.mission;
1123	  m.state = amr_dispatcher_core::dispatcher::MissionState::kActive;
1124	
1125	  // 解析起终点：无 pickup 时用车辆当前位姿作起点；站点缺失或目录未加载直接判负
1126	  const amr_dispatcher_core::catalog::Station* from_st = nullptr;
1127	  const amr_dispatcher_core::catalog::Station* to_st = nullptr;
1128	  const bool catalog_loaded =
1129	      catalog_reloader_ != nullptr && catalog_reloader_->loaded();
1130	  if (catalog_loaded) {
1131	    const auto& catalog = catalog_reloader_->catalog();
1132	    if (!m.pickup_station.empty()) {
1133	      from_st = amr_dispatcher_core::catalog::FindStation(catalog, m.pickup_station);
1134	    }
1135	    if (!m.dropoff_station.empty()) {
1136	      to_st = amr_dispatcher_core::catalog::FindStation(catalog, m.dropoff_station);
1137	    }
1138	  }
1139	  if (m.dropoff_station.empty() || !to_st) {
1140	    RCLCPP_WARN(get_logger(), "Mission %s has no resolvable dropoff station (%s, catalog_loaded=%d), failing",
1141	                m.id.c_str(), m.dropoff_station.c_str(), catalog_loaded);
1142	    if (event_pub_ && event_pub_->is_activated()) {
1143	      amr_dispatcher_interfaces::msg::MissionEvent msg;
1144	      msg.stamp = now();
1145	      msg.mission_id = m.id;
1146	      msg.order_id = m.order_id;
1147	      msg.event = "plan_failed";
1148	      msg.to_state = "FAILED";
1149	      msg.reason = "unknown dropoff station: " + m.dropoff_station;
1150	      event_pub_->publish(msg);
1151	    }
1152	    // 本单已出队但被判负丢弃：Peek 阶段预留的路由锁须就地释放
1153	    //（任务不进 active_missions_，走不到 Complete/Fail 的终态清理）
1154	    if (reservation_table_) {
1155	      reservation_table_->Release(m.id);
1156	    }
1157	    ForgetMissionDispatchState(m.id);
1158	    // ExecuteMission goal 须就地 abort：该分支不经 Complete/Fail，不收口则
1159	    // action 客户端永久悬挂、handle 残留在 execute_goal_handles_（终审 F8）
1160	    //（mission_dispatch_time_ 此刻尚未写入，无需额外遗忘）
1161	    FinishExecuteGoal(m.id, ExecuteFinish::kAbort,
1162	                      "unknown dropoff station: " + m.dropoff_station, 1);
1163	    ReArmQueueStartRequest();  // 本单丢弃后，队列中其余任务仍需能被派发
1164	    return;
1165	  }
1166	
1167	  // 预留成功：持有锁列表（逗号连接）回填任务，供死锁检测长持锁启发式取证
1168	  if (!route_locks.empty()) {
1169	    std::string joined_locks;
1170	    for (const auto& lock_id : route_locks) {
1171	      if (!joined_locks.empty()) {
1172	        joined_locks += ",";
1173	      }
1174	      joined_locks += lock_id;
1175	    }
1176	    m.reservation_id = joined_locks;
1177	  }
1178	
1179	  active_missions_[m.id] = m;
1180	  mission_last_progress_[m.id] = std::chrono::steady_clock::now();
1181	
1182	  // 生成并发布路径：path_tracker 订阅 /plan 后开始输出 /cmd_vel_raw
1183	  amr_dispatcher_core::Pose2D start;
1184	  if (from_st) {
1185	    start = {from_st->x, from_st->y, from_st->yaw};
1186	  } else if (has_odom_) {
1187	    start = {current_pose_.x, current_pose_.y, current_pose_.yaw};
1188	  }
1189	  const amr_dispatcher_core::Pose2D goal{to_st->x, to_st->y, to_st->yaw};
1190	
1191	  const auto waypoints = planner_ ? planner_->Plan(start, goal) : std::vector<amr_dispatcher_core::Pose2D>{};
1192	  if (waypoints.empty() || !plan_pub_ || !plan_pub_->is_activated()) {
1193	    FailMission(m.id, "planner returned empty path");
1194	    return;
1195	  }
1196	
1197	  // 记录派发起点：ExecuteMission feedback 按此直线距离折算 percent_complete
1198	  mission_dispatch_start_[m.id] = {start.x, start.y, start.theta};
1199	  // 派发时刻：ExecuteMission result.total_duration_sec 由此计时
1200	  mission_dispatch_time_[m.id] = std::chrono::steady_clock::now();
1201	
1202	  // 执行后端：action 模式不发 /plan，改为向 /navigate_sequence 发单点 goal
1203	  //（waypoint=规划终点，station_names=[dropoff]）；默认 plan 模式以下路径不变。
1204	  if (navigation_backend_ == "action") {
1205	    if (!nav_client_) {
1206	      FailMission(m.id, "navigate_sequence client not configured");
1207	      return;
1208	    }
1209	    if (!nav_client_->action_server_is_ready()) {
1210	      FailMission(m.id, "navigate_sequence action server not available (is bridge running?)");
1211	      return;
1212	    }
1213	    const auto& wp = waypoints.back();
1214	    NavigateSequence::Goal nav_goal;
1215	    geometry_msgs::msg::PoseStamped ps;
1216	    ps.header.stamp = now();
1217	    ps.header.frame_id = "map";
1218	    ps.pose.position.x = wp.x;
1219	    ps.pose.position.y = wp.y;
1220	    ps.pose.orientation.z = std::sin(wp.theta / 2.0);
1221	    ps.pose.orientation.w = std::cos(wp.theta / 2.0);
1222	    nav_goal.waypoints.push_back(ps);
1223	    nav_goal.station_names.push_back(m.dropoff_station);
1224	    nav_goal.loop = false;
1225	
1226	    rclcpp_action::Client<NavigateSequence>::SendGoalOptions opts;
1227	    const std::string mission_id = m.id;
1228	    opts.goal_response_callback = [this, mission_id](const GoalHandleNavigate::SharedPtr& gh) {
1229	      NavGoalResponseCb(mission_id, gh);
1230	    };
1231	    opts.feedback_callback = [this, mission_id](const GoalHandleNavigate::SharedPtr& gh,
1232	                                                const std::shared_ptr<const NavigateSequence::Feedback> fb) {
1233	      NavFeedbackCb(mission_id, gh, fb);
1234	    };
1235	    opts.result_callback = [this, mission_id](const GoalHandleNavigate::WrappedResult& result) {
1236	      NavResultCb(mission_id, result);
1237	    };
1238	    // 先占住单车执行槽位再发 goal，避免 goal 响应回调前的派发空窗
1239	    pending_nav_mission_id_ = m.id;
1240	    tracking_mission_id_ = m.id;
1241	    nav_client_->async_send_goal(nav_goal, opts);
1242	
1243	    RCLCPP_INFO(get_logger(),
1244	                "Dispatched mission via NavigateSequence: %s (order=%s, type=%s, prio=%d, %s->%s)",
1245	                m.id.c_str(), m.order_id.c_str(), m.type.c_str(), m.priority,
1246	                m.pickup_station.c_str(), m.dropoff_station.c_str());
1247	
1248	    if (event_pub_ && event_pub_->is_activated()) {
1249	      amr_dispatcher_interfaces::msg::MissionEvent msg;
1250	      msg.stamp = now();
1251	      msg.mission_id = m.id;
1252	      msg.order_id = m.order_id;
1253	      msg.event = "active";
1254	      msg.from_state = "PENDING";
1255	      msg.to_state = "ACTIVE";
1256	      msg.reason = "dispatched by scheduler";
1257	      event_pub_->publish(msg);
1258	    }
1259	    return;
1260	  }
1261	
1262	  nav_msgs::msg::Path path_msg;
1263	  path_msg.header.stamp = now();
1264	  path_msg.header.frame_id = "map";
1265	  path_msg.poses.reserve(waypoints.size());
1266	  for (const auto& wp : waypoints) {
1267	    geometry_msgs::msg::PoseStamped ps;
1268	    ps.header = path_msg.header;
1269	    ps.pose.position.x = wp.x;
1270	    ps.pose.position.y = wp.y;
1271	    ps.pose.orientation.z = std::sin(wp.theta / 2.0);
1272	    ps.pose.orientation.w = std::cos(wp.theta / 2.0);
1273	    path_msg.poses.push_back(ps);
1274	  }
1275	  plan_pub_->publish(path_msg);
1276	  tracking_mission_id_ = m.id;
1277	
1278	  RCLCPP_INFO(get_logger(), "Dispatched mission: %s (order=%s, type=%s, prio=%d, %s->%s, %zu waypoints)",
1279	              m.id.c_str(), m.order_id.c_str(), m.type.c_str(), m.priority,
1280	              m.pickup_station.c_str(), m.dropoff_station.c_str(), waypoints.size());
1281	
1282	  if (event_pub_ && event_pub_->is_activated()) {
1283	    amr_dispatcher_interfaces::msg::MissionEvent msg;
1284	    msg.stamp = now();
1285	    msg.mission_id = m.id;
1286	    msg.order_id = m.order_id;
1287	    msg.event = "active";
1288	    msg.from_state = "PENDING";
1289	    msg.to_state = "ACTIVE";
1290	    msg.reason = "dispatched by scheduler";
1291	    event_pub_->publish(msg);
1292	  }
1293	}
