1303	void DispatcherNode::TrackingErrorCb(
1304	    const amr_dispatcher_interfaces::msg::TrackingError::SharedPtr msg) {
1305	  // action 模式的到达信号归 bridge 消费、结果由 NavResultCb 收口：
1306	  // dispatcher 若自行 CompleteMission 会对同一 NavigateSequence goal 发
1307	  // async_cancel_goal，把已完成 goal 打成 CANCELED（审查 I2）
1308	  if (navigation_backend_ == "action") {
1309	    return;
1310	  }
1311	  if (!msg->arrived || tracking_mission_id_.empty()) {
1312	    return;
1313	  }
1314	  const std::string finished_id = tracking_mission_id_;
1315	  tracking_mission_id_.clear();
1316	  mission_last_progress_[finished_id] = std::chrono::steady_clock::now();
1317	  CompleteMission(finished_id, "arrived at goal");
1318	}
