1320	void DispatcherNode::CompleteMission(const std::string& mission_id, const std::string& reason) {
1321	  // 单车执行槽位兜底释放：plan 模式由 TrackingErrorCb 先清（幂等）、
1322	  // action 模式由 NavResultCb 收口——此处不清则槽位残留，后续任务永远无法派发（审查 C1）
1323	  if (tracking_mission_id_ == mission_id) {
1324	    tracking_mission_id_.clear();
1325	  }
1326	  std::string order_id;
1327	  {
1328	    std::lock_guard<std::mutex> lock(active_missions_mutex_);
1329	    auto it = active_missions_.find(mission_id);
1330	    if (it == active_missions_.end()) {
1331	      return;
1332	    }
1333	    order_id = it->second.order_id;
1334	    active_missions_.erase(it);
1335	  }
1336	  // ExecuteMission goal 成功收口；action 模式清在途导航 goal（result 到达前的兜底取消）
1337	  FinishExecuteGoal(mission_id, ExecuteFinish::kSucceed, reason, 0);
1338	  mission_dispatch_time_.erase(mission_id);  // plan 模式无 handle 时的派发时刻遗忘
1339	  ForgetMissionDispatchState(mission_id);    // 路由锁记账/等待记录/派发起点遗忘
1340	  if (navigation_backend_ == "action" && pending_nav_mission_id_ == mission_id) {
1341	    if (nav_client_ && pending_nav_goal_handle_) {
1342	      nav_client_->async_cancel_goal(pending_nav_goal_handle_);
1343	    }
1344	    pending_nav_mission_id_.clear();
1345	    pending_nav_goal_handle_.reset();
1346	  }
1347	
1348	  // 结果处理走 mission_result 行为树：成功分支给资源释放与失败计数复位决策
1349	  amr_dispatcher_core::workflow::MissionResultWorkflowInput result_input;
1350	  result_input.code = amr_dispatcher_core::workflow::MissionActionResultCode::kSucceeded;
1351	  result_input.result_success = true;
1352	  result_input.result_message = reason;
1353	  const auto result_bt = amr_dispatcher_bt::TickMissionResultBehaviorTree(result_input);
1354	  RCLCPP_INFO(get_logger(), "Mission %s result via BT: branch=%s state=%s", mission_id.c_str(),
1355	              result_bt.branch.c_str(),
1356	              result_bt.success ? result_bt.decision.state.c_str() : "tree_failed");
1357	
1358	  // 树失败时回退旧行为（无条件释放），防树异常导致资源泄漏
1359	  if (!result_bt.success || result_bt.decision.release_all_resources) {
1360	    if (reservation_table_) {
1361	      reservation_table_->Release(mission_id);
1362	    }
1363	  }
1364	  if (result_bt.success && result_bt.decision.reset_failure_retry_count) {
1365	    mission_attempts_.erase(mission_id);
1366	    mission_last_progress_.erase(mission_id);
1367	  }
1368	  RCLCPP_INFO(get_logger(), "Mission completed: %s (%s)", mission_id.c_str(), reason.c_str());
1369	  if (event_pub_ && event_pub_->is_activated()) {
1370	    amr_dispatcher_interfaces::msg::MissionEvent msg;
1371	    msg.stamp = now();
1372	    msg.mission_id = mission_id;
1373	    msg.order_id = order_id;
1374	    msg.event = "completed";
1375	    msg.from_state = "ACTIVE";
1376	    msg.to_state = "FINISHED";
1377	    msg.reason = reason;
1378	    event_pub_->publish(msg);
1379	  }
1380	  if (event_log_) {
1381	    amr_dispatcher_core::dispatcher::MissionEvent evt;
1382	    evt.stamp = "now";
1383	    evt.mission_id = mission_id;
1384	    evt.event = "completed";
1385	    evt.message = reason;
1386	    event_log_->Append(evt);
1387	  }
1388	  ReArmQueueStartRequest();  // 队列非空时重新武装 runtime 树的启动请求
1389	}
