#include "amr_dispatcher_ros/mission_identity.hpp"

#include <gtest/gtest.h>

using namespace amr_dispatcher_ros;

// B4：id 与 sequence 必须取自同一次自增的 n，修复 id=n+1 / sequence=n 错位
TEST(MissionIdentity, IdMatchesSequence) {
  std::uint64_t next = 1;
  amr_dispatcher_core::dispatcher::Mission m;
  StampMissionIdentity(m, next);
  EXPECT_EQ(m.id, "m_1");
  EXPECT_EQ(m.sequence, 1u);
  EXPECT_EQ(next, 2u);
}

// B4：连续两次戳记单调递增
TEST(MissionIdentity, SequenceIncrementsMonotonically) {
  std::uint64_t next = 1;
  amr_dispatcher_core::dispatcher::Mission a, b;
  StampMissionIdentity(a, next);
  StampMissionIdentity(b, next);
  EXPECT_EQ(a.sequence + 1, b.sequence);
  EXPECT_EQ(a.id, "m_" + std::to_string(a.sequence));
  EXPECT_EQ(b.id, "m_" + std::to_string(b.sequence));
}

// B4：id 前缀可定制（preempt_/dock 场景仍走同一戳记路径）
TEST(MissionIdentity, CustomPrefix) {
  std::uint64_t next = 7;
  amr_dispatcher_core::dispatcher::Mission m;
  StampMissionIdentity(m, next, "preempt_");
  EXPECT_EQ(m.id, "preempt_7");
  EXPECT_EQ(m.sequence, 7u);
}

#include "amr_dispatcher_ros/nav_pose_builder.hpp"

#include <gtest/gtest.h>

#include <cmath>

using namespace amr_dispatcher_ros;

namespace {

geometry_msgs::msg::PoseStamped MakeWp(double x, double y, double qz, double qw) {
  geometry_msgs::msg::PoseStamped ps;
  ps.pose.position.x = x;
  ps.pose.position.y = y;
  ps.pose.orientation.z = qz;
  ps.pose.orientation.w = qw;
  return ps;
}

}  // namespace

// B3：单航点必须保留调用方给的原始四元数（不得被 atan2 覆盖为单位姿态）。
// 例如 dispatcher 在 action 后端下用 wp.theta 编码站点朝向，覆盖成 yaw=0 会让
// 车辆到站后回正——丢失终端姿态约束。
TEST(NavPoseBuilder, SingleWaypointPreservesOrientation) {
  const double target_yaw = 1.2;  // 任意非零朝向
  const double qz = std::sin(target_yaw / 2.0);
  const double qw = std::cos(target_yaw / 2.0);
  const auto out = BuildNavPoses({MakeWp(3.0, 4.0, qz, qw)});
  ASSERT_EQ(out.size(), 1u);
  EXPECT_DOUBLE_EQ(out[0].pose.position.x, 3.0);
  EXPECT_DOUBLE_EQ(out[0].pose.position.y, 4.0);
  EXPECT_DOUBLE_EQ(out[0].pose.orientation.z, qz);
  EXPECT_DOUBLE_EQ(out[0].pose.orientation.w, qw);
  EXPECT_EQ(out[0].header.frame_id, "map");
}

// B3：多航点时仍按相邻点 atan2 重写航向（与原行为一致）
TEST(NavPoseBuilder, MultiWaypointOverwritesOrientation) {
  const auto out = BuildNavPoses({MakeWp(0.0, 0.0, 0.9, 0.1),  // 起点原始姿态应被覆盖
                                  MakeWp(1.0, 0.0, 0.0, 1.0)});
  ASSERT_EQ(out.size(), 2u);
  // 航向 = atan2(0-0, 1-0) = 0 -> z=0 w=1
  EXPECT_DOUBLE_EQ(out[0].pose.orientation.z, 0.0);
  EXPECT_DOUBLE_EQ(out[0].pose.orientation.w, 1.0);
  // 末点沿用最后一段朝向 -> 也是 yaw=0
  EXPECT_DOUBLE_EQ(out[1].pose.orientation.z, 0.0);
  EXPECT_DOUBLE_EQ(out[1].pose.orientation.w, 1.0);
}

// B3：空输入返回空
TEST(NavPoseBuilder, EmptyInputReturnsEmpty) {
  EXPECT_TRUE(BuildNavPoses({}).empty());
}

#include "amr_dispatcher_ros/safety_publish_decision.hpp"

#include <gtest/gtest.h>

#include <chrono>

using namespace amr_dispatcher_ros;
using namespace std::chrono_literals;

namespace {

PeriodicPublishInput MakeInput() {
  PeriodicPublishInput in;
  in.now = std::chrono::steady_clock::now();
  in.last_raw_stamp = in.now;
  in.has_last_raw_stamp = true;
  in.has_decision = true;
  in.last_linear_x_mps = 0.5;
  in.last_angular_z_radps = 0.2;
  in.heartbeat_timeout = 500ms;
  return in;
}

}  // namespace

// B1：estop/auto_fault/bumper/critical 任一激活 -> 周期帧强制零速
TEST(SafetyPublishDecision, EStopForcesZero) {
  auto in = MakeInput();
  in.estop_or_fault = true;
  const auto out = ComputePeriodicPublish(in);
  EXPECT_EQ(out.kind, PeriodicPublishKind::kZero);
  EXPECT_DOUBLE_EQ(out.linear_x_mps, 0.0);
  EXPECT_DOUBLE_EQ(out.angular_z_radps, 0.0);
  EXPECT_EQ(out.reason, "estop");
}

TEST(SafetyPublishDecision, BumperForcesZero) {
  auto in = MakeInput();
  in.bumper = true;
  const auto out = ComputePeriodicPublish(in);
  EXPECT_EQ(out.kind, PeriodicPublishKind::kZero);
  EXPECT_EQ(out.reason, "bumper");
}

TEST(SafetyPublishDecision, CriticalDecisionForcesZero) {
  auto in = MakeInput();
  in.decision_critical = true;
  const auto out = ComputePeriodicPublish(in);
  EXPECT_EQ(out.kind, PeriodicPublishKind::kZero);
  EXPECT_EQ(out.reason, "critical_event");
}

// B1：/cmd_vel_raw 超过 heartbeat_timeout 未收到 -> 周期零速兜底
TEST(SafetyPublishDecision, StaleRawForcesZero) {
  auto in = MakeInput();
  in.last_raw_stamp = in.now - 600ms;
  const auto out = ComputePeriodicPublish(in);
  EXPECT_EQ(out.kind, PeriodicPublishKind::kZero);
  EXPECT_EQ(out.reason, "cmd_vel_raw_stale");
}

// 边界：恰好等于阈值不算过期（严格大于才触发）
TEST(SafetyPublishDecision, BoundaryTimeoutNotStale) {
  auto in = MakeInput();
  in.last_raw_stamp = in.now - 500ms;
  const auto out = ComputePeriodicPublish(in);
  EXPECT_EQ(out.kind, PeriodicPublishKind::kDecision);
  EXPECT_DOUBLE_EQ(out.linear_x_mps, 0.5);
  EXPECT_DOUBLE_EQ(out.angular_z_radps, 0.2);
}

// 正常路径：重放最近一次裁决结果
TEST(SafetyPublishDecision, ReplaysLastDecision) {
  auto in = MakeInput();
  in.last_raw_stamp = in.now - 100ms;  // 新鲜
  const auto out = ComputePeriodicPublish(in);
  EXPECT_EQ(out.kind, PeriodicPublishKind::kDecision);
  EXPECT_DOUBLE_EQ(out.linear_x_mps, 0.5);
  EXPECT_DOUBLE_EQ(out.linear_y_mps, 0.0);
  EXPECT_DOUBLE_EQ(out.angular_z_radps, 0.2);
}

// 从未收到过 raw：不发任何帧（系统还没开始运动，持续零速无意义）
TEST(SafetyPublishDecision, NeverReceivedSkips) {
  auto in = MakeInput();
  in.has_decision = false;
  in.has_last_raw_stamp = false;
  const auto out = ComputePeriodicPublish(in);
  EXPECT_EQ(out.kind, PeriodicPublishKind::kSkip);
}

