      amr_dispatcher_core::chassis::ChassisCommand zero_cmd;
      std::string zero_err;
      backend_ctrl_->current()->WriteCommand(zero_cmd, &zero_err);
      if (!stale_zero_active_) {
        stale_zero_active_ = true;
        RCLCPP_WARN(get_logger(),
                    "cmd_vel_safe stale for %lld ms, writing zero frame fallback",
                    static_cast<long long>(std::chrono::duration_cast<std::chrono::milliseconds>(age).count()));
      }
    } else if (stale_zero_active_) {
      // 恢复收流，复位一次性告警
      stale_zero_active_ = false;
    }
  }
```

Wait — should write zero every poll while stale? Yes, that's simplest and keeps chassis commanded to zero. Where to put it: after backend-open check passes (after the early-return block). But careful: WriteCommand failure would RecordLoss? Keep simple — don't record loss for zero writes (they're best-effort). Place it right after the `if (!backend open) {...return;}` block.

