  resp->success = true;
  resp->message = "Snapshot captured";
  resp->mission_state = "IDLE";
  resp->queue_size = queue_ ? static_cast<int32_t>(queue_->size()) : 0;
  std::lock_guard<std::mutex> lock(active_missions_mutex_);
