1044	void DispatcherNode::ScheduleTick() {
1045	  // 已受理的 ExecuteMission action 取消需在提前返回之前处理（10Hz 延迟 ≤100ms）
1046	  ProcessActionCancels();
1047	  if (!queue_ || queue_->empty()) {
1048	    return;
1049	  }
1050	  const std::size_t max_active = get_parameter("max_active_missions").as_int();
1051	  if (active_missions_.size() >= max_active) {
1052	    return;
1053	  }
1054	
1055	  // 单车执行模型：同时只有一条 /plan 在跟踪，其余任务保持 active 等待车辆空闲
1056	  if (!tracking_mission_id_.empty()) {
1057	    return;
1058	  }
1059	
1060	  // 行为树出队派发门控：runtime 树按"空闲 + 启动请求"给派发决策，
1061	  // 未请求启动时即使队列有任务也不出队（启动请求由提单/入队/结果链武装）。
1062	  amr_dispatcher_bt::MissionRuntimeBehaviorTreeInput runtime_input;
1063	  runtime_input.tick.mission_active = !tracking_mission_id_.empty();
1064	  runtime_input.tick.queue_start_requested = queue_start_requested_;
1065	  const auto runtime_result = amr_dispatcher_bt::TickMissionRuntimeBehaviorTree(runtime_input);
1066	  if (!runtime_result.success || !runtime_result.decision.start_queued_mission) {
1067	    return;
1068	  }
1069	  queue_start_requested_ = false;  // 启动请求被本次派发消费
1070	
1071	  // Peek→Reserve→Pop（节点单线程，Peek 与 Pop 之间无竞态）：
1072	  // 先为队首任务规划路由锁并预留，成功才出队继续派发；失败则任务留在队列、
1073	  // 发 reservation_denied 事件、重新武装启动请求后本 tick 返回——既不丢任务也不违反封路。
1074	  const auto* peeked = queue_->Peek();
1075	  if (!peeked) {
1076	    return;  // 队列任务全部暂停：与 PopNext 失败等价，本 tick 结束
1077	  }
1078	  const std::string candidate_id = peeked->id;
1079	  const std::string candidate_order_id = peeked->order_id;

