  rclcpp_action::Server<ExecuteMission>::SharedPtr execute_action_server_;
  // NavigateSequence 客户端（navigation_backend=action 时向桥接节点发单点 goal）
  rclcpp_action::Client<NavigateSequence>::SharedPtr nav_client_;
